// Parse request for market report parameters
const body = $input.first().json.body;

// Support multiple neighborhoods in single request
const neighborhoods = body.neighborhoods || body.neighborhood || '';
const neighborhoodList = neighborhoods.split(',').map(n => n.trim()).filter(n => n);

if (neighborhoodList.length === 0) {
  throw new Error('Please provide at least one neighborhood');
}

const reports = neighborhoodList.map(neighborhood => ({
  json: {
    neighborhood,
    recipientEmail: body.email || body.recipient || '',
    recipientName: body.name || 'Client',
    includeCharts: body.includeCharts !== false,
    reportType: body.reportType || 'comprehensive' // 'comprehensive' | 'quick'
  }
}));

return reports;

// Calculate market statistics from MLS data
const requestData = $('Parse Report Request').item.json;
const salesData = $('Fetch 90-Day Sales Data').item.json.value || [];
const activeData = $('Fetch Active Listings').item.json.value || [];

if (salesData.length === 0) {
  return [{
    json: {
      ...requestData,
      error: 'No sales data found for this neighborhood',
      hasData: false
    }
  }];
}

// Calculate sold statistics
const soldPrices = salesData.map(s => s.ClosePrice || s.ListPrice).filter(p => p > 0);
const daysOnMarket = salesData.map(s => s.DaysOnMarket).filter(d => d >= 0);
const pricePerSqft = salesData
  .filter(s => s.ClosePrice > 0 && s.LivingArea > 0)
  .map(s => s.ClosePrice / s.LivingArea);

// Calculate averages
const avgSoldPrice = Math.round(soldPrices.reduce((a, b) => a + b, 0) / soldPrices.length);
const medianSoldPrice = soldPrices.sort((a, b) => a - b)[Math.floor(soldPrices.length / 2)];
const avgDaysOnMarket = Math.round(daysOnMarket.reduce((a, b) => a + b, 0) / daysOnMarket.length);
const avgPricePerSqft = Math.round(pricePerSqft.reduce((a, b) => a + b, 0) / pricePerSqft.length);

// Calculate active listings stats
const activePrices = activeData.map(a => a.ListPrice).filter(p => p > 0);
const avgActivePrice = activePrices.length > 0 
  ? Math.round(activePrices.reduce((a, b) => a + b, 0) / activePrices.length)
  : 0;

// Market temperature (simple heuristic)
let marketTemp = 'Balanced';
if (avgDaysOnMarket < 15 && salesData.length > activeData.length) {
  marketTemp = 'Hot (Seller\'s Market)';
} else if (avgDaysOnMarket > 60 && activeData.length > salesData.length * 1.5) {
  marketTemp = 'Cool (Buyer\'s Market)';
} else if (avgDaysOnMarket < 30) {
  marketTemp = 'Warm';
}

// Get recent comparable sales (last 10)
const recentSales = salesData
  .sort((a, b) => new Date(b.CloseDate) - new Date(a.CloseDate))
  .slice(0, 10)
  .map(s => ({
    address: s.UnparsedAddress || 'Address N/A',
    price: s.ClosePrice || s.ListPrice,
    date: s.CloseDate,
    beds: s.BedroomsTotal,
    baths: s.BathroomsTotalInteger,
    sqft: s.LivingArea,
    daysOnMarket: s.DaysOnMarket
  }));

// Get current listings to watch (4 best values)
const listingsToWatch = activeData
  .filter(a => a.LivingArea > 0)
  .map(a => ({
    ...a,
    pricePerSqft: a.ListPrice / a.LivingArea
  }))
  .sort((a, b) => a.pricePerSqft - b.pricePerSqft)
  .slice(0, 4);

return [{
  json: {
    ...requestData,
    hasData: true,
    stats: {
      avgSoldPrice,
      medianSoldPrice,
      avgActivePrice,
      avgDaysOnMarket,
      avgPricePerSqft,
      totalSold: salesData.length,
      activeListings: activeData.length,
      marketTemp
    },
    recentSales,
    listingsToWatch,
    rawSalesData: salesData,
    rawActiveData: activeData
  }
}];

